const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const reykjavikPoint = ee.Geometry.Point([-21.9426, 64.1466]);
    const reykjavik = reykjavikPoint.buffer(5000); // 5km buffer for a stable mean
    const snaefellsnes = ee.Geometry.Polygon([
        [
            [-23.8, 64.75],
            [-23.8, 64.95],
            [-22.3, 64.95],
            [-22.3, 64.75]
        ]
    ]);
    const startDate = '2016-01-01';
    const endDate = '2016-12-31';
    const band = 'avg_rad';
    const scale = 1000;

    // 2. Data Acquisition
    const viirsCollection = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
        .filterDate(startDate, endDate)
        .select(band);

    const imageCount = viirsCollection.size().getInfo();
    if (imageCount === 0) {
        console.log("Evidence: No VIIRS images found for 2016.");
        console.log("A"); // C1
        return;
    }
    console.log(`Image Count for 2016: ${imageCount}`);

    // 3. Processing: Create a single mean image for the year
    const yearlyMeanImage = viirsCollection.mean();

    // 4. Calculation: Reduce regions to get mean light intensity
    const reykjavikStats = yearlyMeanImage.reduceRegion({
        reducer: ee.Reducer.mean().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        geometry: reykjavik,
        scale: scale,
        maxPixels: 1e9
    }).getInfo();

    const snaefellsnesStats = yearlyMeanImage.reduceRegion({
        reducer: ee.Reducer.mean().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        geometry: snaefellsnes,
        scale: scale,
        maxPixels: 1e9
    }).getInfo();

    // 5. Validation & Final Answer
    const reykjavikValue = reykjavikStats[band + '_mean'];
    const reykjavikPixels = reykjavikStats[band + '_count'];
    const snaefellsnesValue = snaefellsnesStats[band + '_mean'];
    const snaefellsnesPixels = snaefellsnesStats[band + '_count'];

    console.log(`Reykjavík Mean Radiance: ${reykjavikValue ? reykjavikValue.toFixed(2) : 'N/A'}`);
    console.log(`Reykjavík Valid Pixels: ${reykjavikPixels}`);
    console.log(`Snæfellsnes Mean Radiance: ${snaefellsnesValue ? snaefellsnesValue.toFixed(2) : 'N/A'}`);
    console.log(`Snæfellsnes Valid Pixels: ${snaefellsnesPixels}`);

    if (reykjavikPixels === 0 || snaefellsnesPixels === 0) {
        console.log("Evidence: No valid pixels in one or both geometries.");
        console.log("C2");
        return;
    }

    if (reykjavikValue === null || snaefellsnesValue === null || isNaN(reykjavikValue) || isNaN(snaefellsnesValue)) {
        console.log("Evidence: Calculation resulted in a null or NaN value.");
        console.log("C3");
        return;
    }

    if (reykjavikValue > snaefellsnesValue) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(e => {
    console.error(`An error occurred: ${e}`);
    console.log("D");
});
